+        this.length = length;
+        this.hash = hash;
+        this.highOrderFactor = highOrderFactor;
+    }
+
+    static CompiledPattern compile(CharSequence pattern, int radix, int modulus) {
+        int m = pattern.length();
+        int h = 1;
+        for (int i = 0; i < m - 1; i++) {
+            h = (h * radix) % modulus;
+        }
+        int hash = 0;
+        for (int i = 0; i < m; i++) {
+            hash = (radix * hash + pattern.charAt(i)) % modulus;
+        }
